changeSet.sql:
ALTER TABLE risks ALTER COLUMN damage_operations TYPE FLOAT USING ( CASE WHEN damage_operations IS NULL THEN '0' WHEN trim(damage_operations) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN trim(damage_operations) WHEN lower(trim(damage_operations)) IN ('muito alta', 'muito alto') THEN '10' WHEN lower(trim(damage_operations)) IN ('alta', 'alto') THEN '8' WHEN lower(trim(damage_operations)) IN ('média', 'medio', 'médio', 'media') THEN '5' WHEN lower(trim(damage_operations)) IN ('baixa', 'baixo') THEN '2' ELSE '0' END )::FLOAT, ALTER COLUMN damage_individuals TYPE FLOAT USING ( CASE WHEN damage_individuals IS NULL THEN '0' WHEN trim(damage_individuals) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN trim(damage_individuals) WHEN lower(trim(damage_individuals)) IN ('muito alta', 'muito alto') THEN '10' WHEN lower(trim(damage_individuals)) IN ('alta', 'alto') THEN '8' WHEN lower(trim(damage_individuals)) IN ('média', 'medio', 'médio', 'media') THEN '5' WHEN lower(trim(damage_individuals)) IN ('baixa', 'baixo') THEN '2' ELSE '0' END )::FLOAT, ALTER COLUMN damage_other_orgs TYPE FLOAT USING ( CASE WHEN damage_other_orgs IS NULL THEN '0' WHEN trim(damage_other_orgs) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN trim(damage_other_orgs) WHEN lower(trim(damage_other_orgs)) IN ('muito alta', 'muito alto') THEN '10' WHEN lower(trim(damage_other_orgs)) IN ('alta', 'alto') THEN '8' WHEN lower(trim(damage_other_orgs)) IN ('média', 'medio', 'médio', 'media') THEN '5' WHEN lower(trim(damage_other_orgs)) IN ('baixa', 'baixo') THEN '2' ELSE '0' END )::FLOAT;
UPDATE risks SET damage_operations = COALESCE(damage_operations, 0), damage_individuals = COALESCE(damage_individuals, 0), damage_other_orgs = COALESCE(damage_other_orgs, 0);
ALTER TABLE risks ADD COLUMN damage_assets FLOAT, ADD COLUMN general_risk FLOAT, ADD COLUMN priority VARCHAR(2);
UPDATE risks SET damage_assets = COALESCE(damage_assets, damage_operations, 0), priority = COALESCE(priority, 'P3');
UPDATE risks SET general_risk = (damage_operations + damage_assets + damage_individuals + damage_other_orgs) / 4.0;
ALTER TABLE risks ALTER COLUMN damage_operations SET NOT NULL, ALTER COLUMN damage_individuals SET NOT NULL, ALTER COLUMN damage_other_orgs SET NOT NULL, ALTER COLUMN damage_assets SET NOT NULL, ALTER COLUMN general_risk SET NOT NULL, ALTER COLUMN priority SET NOT NULL;
ALTER TABLE risks DROP COLUMN risk_level;
